function pinCard(){
  const ll = PIN.ll; if (!ll) return;
  const lng = ll[0], lat = ll[1], n = pinNear(ll), LL = lat.toFixed(6) + ',' + lng.toFixed(6);
  let vn = null; try { if (window.proj4) { const r = proj4('EPSG:4326', VN_DEF(), [lng, lat]); vn = [r[1], r[0]]; } } catch (e) {}
  const w = inWard(ll), pi = (typeof vnInParcel === 'function') ? vnInParcel(ll) : null;
  const addr = [n.sn ? 'Số ' + n.sn.t : '', n.st ? n.st.n : ''].filter(Boolean).join(' ');
  const title = n.sn && n.sn.d < 15 ? addr : 'Ghim đã thả';
  const sub = (n.sn || n.st ? 'Gần ' + addr + ', ' : '') + (n.kp ? n.kp + ', ' : '') + (w === false ? 'ngoài phường Bình Tân' : 'Phường Bình Tân') + ', Hồ Chí Minh';
  const g = 'https:' + '/' + '/' + 'www.google.com/maps/';
  const svUrl = g + '@?api=1&map_action=pano&viewpoint=' + LL;
  // Ảnh đường phố: có khóa Google Maps Embed API (GMAPS_KEY trong Mã.gs) thì xem ngay trong khung, chưa có thì bấm để mở Google Maps
  const photo = C.GK
    ? '<iframe class="svf" loading="lazy" allowfullscreen referrerpolicy="no-referrer-when-downgrade" src="' + g + 'embed/v1/streetview?key=' + encodeURIComponent(C.GK) + '&location=' + LL + '&fov=80"></iframe>'
    : '<a class="svph" href="' + svUrl + '" target="_blank" rel="noopener"><span>📷</span>Xem ảnh đường phố tại đây (Google Street View)</a>';
  const ic = d => '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + d + '</svg>';
  const IC = {dir:'<path d="M3 11.5 12 3l9 8.5-9 9.5z"/><path d="M9 13v-2.5h5V8l3 3-3 3v-2.5h-3.5V13"/>', go:'<path d="M12 2 19 21 12 17 5 21z"/>', share:'<path d="M4 12v7a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-7"/><path d="m16 6-4-4-4 4"/><path d="M12 2v13"/>', copy:'<rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15V5a2 2 0 0 1 2-2h10"/>',
    pin:'<path d="M12 21s-7-6.2-7-11.5A7 7 0 0 1 19 9.5C19 14.8 12 21 12 21z"/><circle cx="12" cy="9.5" r="2.5"/>', home:'<path d="m3 11 9-8 9 8"/><path d="M5 10v10h14V10"/>', map:'<path d="m9 4-6 2v14l6-2 6 2 6-2V4l-6 2z"/><path d="M9 4v14M15 6v14"/>', grid:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 12h18M12 3v18"/>', xy:'<circle cx="12" cy="12" r="8"/><path d="M12 2v4M12 18v4M2 12h4M18 12h4"/>'};
  const R = (i, t, extra) => '<div class="grow">' + ic(IC[i]) + '<div>' + t + (extra ? '<small>' + extra + '</small>' : '') + '</div></div>';
  geoEl.dataset.k = 'pin'; geoEl.classList.remove('err'); geoEl.classList.add('gm');
  document.getElementById('geoT').textContent = title;
  document.getElementById('geoC').innerHTML =
    '<div class="gsub">' + esc(sub) + '</div>' +
    '<div class="gact"><a class="pri" href="' + g + 'dir/?api=1&destination=' + LL + '" target="_blank" rel="noopener">' + ic(IC.dir) + 'Đường đi</a>' +
    '<a href="' + g + 'dir/?api=1&destination=' + LL + '&dir_action=navigate" target="_blank" rel="noopener">' + ic(IC.go) + 'Bắt đầu</a>' +
    '<button id="pinShare">' + ic(IC.share) + 'Chia sẻ</button><button id="pinCopy">' + ic(IC.copy) + 'Sao chép</button></div>' +
    photo +
    R('pin', esc(sub)) +
    (n.sn ? R('home', 'Số nhà gần nhất: <b>' + esc(n.sn.t) + '</b>', 'cách khoảng ' + fmt(n.sn.d, 0) + ' m') : '') +
    (PIN.qi != null && D.qh[PIN.qi] ? R('map', '<a href="#" id="pinQH">' + esc((D.qh[PIN.qi].k ? D.qh[PIN.qi].k + ' · ' : '') + D.qh[PIN.qi].n) + ' ›</a>', 'Quy hoạch sử dụng đất') : '') +
    (pi != null ? R('grid', (AUTH.admin() ? 'Thửa ' + esc(TD.codes[pi]) + ' · ' : 'Thửa đất · ') + fmt(TD.area[pi], 1) + ' m²') : '') +
    R('xy', LL + (vn ? '<br>VN-2000: ' + vn[0].toFixed(2) + ' ; ' + vn[1].toFixed(2) : '')) +
    (vn ? '<div class="gact" style="margin-top:8px"><button id="pinVN">' + ic(IC.xy) + 'Đưa vào ô VN2000</button></div>' : '');
  geoEl.hidden = false; document.getElementById('legend').classList.add('under');
  const link = g + 'search/?api=1&query=' + LL, txt = (title !== 'Ghim đã thả' ? title + '\n' : '') + LL + (vn ? '\nVN-2000: ' + vn[0].toFixed(2) + ';' + vn[1].toFixed(2) : '');
  document.getElementById('pinShare').onclick = () => { if (navigator.share) navigator.share({title, text:txt, url:link}).catch(() => {}); else (navigator.clipboard ? navigator.clipboard.writeText(txt + '\n' + link) : Promise.reject()).then(() => { document.getElementById('pinShare').lastChild.textContent = 'Đã chép link ✓'; }, () => prompt('Link vị trí:', link)); };
  document.getElementById('pinCopy').onclick = () => { (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject()).then(() => { document.getElementById('pinCopy').lastChild.textContent = 'Đã chép ✓'; }, () => prompt('Sao chép:', txt)); };
  const qa = document.getElementById('pinQH'); if (qa) qa.onclick = ev => { ev.preventDefault(); showQH(PIN.qi); };
  const vb = document.getElementById('pinVN'); if (vb) vb.onclick = () => { openVN(); document.getElementById('vnIn').value = vn[0].toFixed(2) + ';' + vn[1].toFixed(2); };
}
